// A library of everyday Russian texts from a Moscow residential district, winter 2007–2009,
// each with an English translation. For notices, posters, graffiti, shop labels, metro and
// street signs and text messages. Fictional brands and phone numbers; no politics.
//
// Every item: { id, kind, ru, en, style } where `style` is the ui.showNote style used when the
// player reads it ('notice' | 'hand' | 'paper' | 'sign' | 'ticket' | 'screen').
// Optional: title (heading), footer (signature / small print), sub (sub-category), look (how
// it is drawn in the world), tear (text on tear-off strips), paper, ink, layout, colors, brand.

const N = (o) => ({ kind: 'notice', style: 'notice', look: 'printed', ...o })
const H = (o) => ({ kind: 'notice', style: 'hand', look: 'handwritten', paper: 'notebook', ...o })

