export const TEXTS = { NOTICES, ADS, GRAFFITI, SHOP, METRO, STREET, SMS }
export const ALL_TEXTS = [...NOTICES, ...ADS, ...GRAFFITI, ...SHOP, ...METRO, ...STREET, ...SMS]
const BY_ID = new Map(ALL_TEXTS.map(t => [t.id, t]))
const BY_KIND = {}
for (const t of ALL_TEXTS) (BY_KIND[t.kind] ||= []).push(t)

/** Look up a text by id. */
export function getText(id) { return BY_ID.get(id) ?? null }

/** All texts of a kind ('notice'|'ad'|'graffiti'|'shop'|'metro'|'street'|'sms'), optionally filtered. */
export function textsOf(kind, filter = {}) {
  let list = BY_KIND[kind] ?? []
  if (filter.sub) list = list.filter(t => t.sub === filter.sub || (Array.isArray(filter.sub) && filter.sub.includes(t.sub)))
  if (filter.look) list = list.filter(t => t.look === filter.look || (Array.isArray(filter.look) && filter.look.includes(t.look)))
  if (filter.exclude) list = list.filter(t => !filter.exclude.includes(t.id))
  return list
}

/** Deterministic pick by seed (any number). */
export function pickText(kind, seed = 1, filter = {}) {
  const list = textsOf(kind, filter)
  if (!list.length) return null
  let h = (Math.floor(Math.abs(seed) * 2654435761) ^ 0x5bd1e995) >>> 0
  h = Math.imul(h ^ (h >>> 15), 0x2c1b3c6d) >>> 0
  h = (h ^ (h >>> 12)) >>> 0
  return list[h % list.length]
}
